INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(12601, 'Job 31:1', 'Job', 31, 1, '&nbsp;ما د خپل ځان سره يو لوظ کړے دے چې يوې پېغلې ته به هم په غلط نظر باندې نۀ ګورم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12602, 'Job 31:2', 'Job', 31, 2, '&nbsp;پاس په آسمان کښې خُدائ پاک به زما دپاره څۀ کوى، او په قادر خُدائ کښې به زما ميراث څۀ وى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12603, 'Job 31:3', 'Job', 31, 3, '&nbsp;افت په ګناهګارو خلقو نۀ راغورزيږى څۀ، او مصيبت په هغه خلقو چې څوک بدعمله وى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12604, 'Job 31:4', 'Job', 31, 4, '&nbsp;زۀ چې څۀ هم کوم نو هغۀ ته پته ده، او زما په هر قدم باندې يې نظر دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12605, 'Job 31:5', 'Job', 31, 5, '&nbsp;ما کله چا ته دروغ وئيلى دى څۀ، او يا مې چا له دوکه ورکړې ده څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12606, 'Job 31:6', 'Job', 31, 6, '&nbsp;نو زۀ دې د اِنصاف په تله کښې وتللے شم، چې خُدائ پاک ته زما د صداقت پته ولګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12607, 'Job 31:7', 'Job', 31, 7, '&nbsp;کۀ زما قدم د هغۀ د لارې نه اوړېدلے وى، او زما زړۀ زما د سترګو په خواهش پسې تلے وى، يا کۀ د څۀ بل څۀ ګناه شوى وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12608, 'Job 31:8', 'Job', 31, 8, '&nbsp;نو ما پرېږده چې څۀ وکَرم او نور يې وخورى، او زما کَرلے فصل دې تباه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12609, 'Job 31:9', 'Job', 31, 9, '&nbsp;کۀ زۀ د ګاونډى په ښځه باندې مئين شم، او د هغې په دروازه کښې په طمع کښېنم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12610, 'Job 31:10', 'Job', 31, 10, '&nbsp;نو بيا دې زما ښځه د نورو دپاره مېچن وکړى، او پرېږده چې نور سړى د هغې سره څملى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12611, 'Job 31:11', 'Job', 31, 11, '&nbsp;ځکه چې دا به د شرم نه ډک کار وى، او دا به د سزا حقدار جرم وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12612, 'Job 31:12', 'Job', 31, 12, '&nbsp;ځکه چې دا به د دوزخ په شان تباه کوونکے اور وى، او زما به هر څۀ تباه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12613, 'Job 31:13', 'Job', 31, 13, '&nbsp;کۀ زما وينځې يا غلام ما ته شکايت کړے وى، او ما هغوئ سره اِنصاف نۀ وى کړے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12614, 'Job 31:14', 'Job', 31, 14, '&nbsp;نو بيا زۀ خُدائ پاک ته څنګه مخامخ کېدے شم؟ کله چې هغه حِساب کِتاب کوى نو زۀ څۀ جواب ورکړم؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12615, 'Job 31:15', 'Job', 31, 15, '&nbsp;هغه خُدائ پاک چې زۀ يې پېدا کړے يم، زما نوکران يې هم پېدا کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12616, 'Job 31:16', 'Job', 31, 16, '&nbsp;ما کله هم د غريبانانو مدد نۀ دے پرېښے، او نۀ مې کونډې مايُوسه کړې دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12617, 'Job 31:17', 'Job', 31, 17, '&nbsp;يا مې په روټۍ کښې د شومتوب نه کار اخستے وى، او دا مې يتيمانانو له نۀ وى ورکړې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12618, 'Job 31:18', 'Job', 31, 18, '&nbsp;ځکه چې د ځوانۍ نه ما د يتيمانانو خيال لکه د يو پلار په شان ساتلے دے، او ټول عُمر مې په کونډو پام کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12619, 'Job 31:19', 'Job', 31, 19, '&nbsp;کۀ ما څوک په تکليف کښې ليدلے وى چې جامې يې نۀ وى، يا دومره غريب وى چې جامې نۀ شى اخستے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12620, 'Job 31:20', 'Job', 31, 20, '&nbsp;نو ما ورله د کپړو دپاره د خپلو ګډو وړئ ورکړې ده چې ځان په کښې ګرم کړى، او هغوئ زما شکريه ادا کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12621, 'Job 31:21', 'Job', 31, 21, '&nbsp;کۀ ما د يتيمانانو خِلاف خپل لاس اوچت کړے وى، ځکه چې ما ته پته وه چې په عدالت کښې زما ملګرى شته دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12622, 'Job 31:22', 'Job', 31, 22, '&nbsp;نو زما لاسونه دې مات شى، او زما د تن نه دې پرې کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12623, 'Job 31:23', 'Job', 31, 23, '&nbsp;ځکه چې زۀ د خُدائ پاک د مصيبت نه په يره کښې وم، او زۀ د هغۀ د شان او شوکت په وړاندې نۀ شوم ودرېدلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12624, 'Job 31:24', 'Job', 31, 24, '&nbsp;کۀ ما په سرو زرو يقين کړے وے، يا مې په سوچه سرو زرو باندې اعتبار کړے وے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12625, 'Job 31:25', 'Job', 31, 25, '&nbsp;کۀ ما د خپل مال دولت په وجه خوشحالى کړے وے، يا چې ما سره ډېر څۀ دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12626, 'Job 31:26', 'Job', 31, 26, '&nbsp;کۀ ما په هغه وخت کښې نمر ته کتلے په کوم وخت کښې چې دا ځلېدو، يا مې سپوږمۍ ته کتلے چې د شان او شوکت سره روانه وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12627, 'Job 31:27', 'Job', 31, 27, '&nbsp;او کۀ زما زړۀ په پټه د دې عبادت شروع کړے وے، او د دُعا دپاره مې ورته لاسونه اوچت کړے وے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12628, 'Job 31:28', 'Job', 31, 28, '&nbsp;دا به يو غلطى وے او قاضيانو به د دې په وجه سزا راکړے وے، ځکه چې زۀ به د خُدائ تعالىٰ مجرم وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12629, 'Job 31:29', 'Job', 31, 29, '&nbsp;کۀ زۀ د هغه خلقو په تباهۍ باندې خوشحاله وے چا چې زما نه نفرت کولو، يا مې په هغه وخت کښې خوشحالى کولے چې بدعملى په هغوئ باندې غالِبه شوې وه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12630, 'Job 31:30', 'Job', 31, 30, '&nbsp;ما په خپله خولۀ باندې داسې ګناه نۀ ده کړې چې هغوئ ته مې د مرګ ښېرې کړے وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12631, 'Job 31:31', 'Job', 31, 31, '&nbsp;زما په خاندان کښې هر يو کس ته پته ده، چې زما کور ته څوک هم راغلى دى نو د هغوئ ښۀ مېلمستيا شوې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12632, 'Job 31:32', 'Job', 31, 32, '&nbsp;ما په پردو خلقو هيڅکله بې‌غورى نۀ ده کړې چې هغوئ په کوڅه کښې شپه تېره کړى، او ما مسافرو ته خپلې دروازې کولاو ساتلې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12633, 'Job 31:33', 'Job', 31, 33, '&nbsp;کۀ ما خپله ګناه د نورو خلقو په شان پټه کړې وې، او غلطى مې په خپل زړۀ کښې پټه ساتلې وې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12634, 'Job 31:34', 'Job', 31, 34, '&nbsp;ځکه چې زۀ د ګڼې نه يا د خلقو د بې‌عزتۍ نه يرېدلے يم، چې غلے پاتې يم او د کور نه نۀ يم وتلے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12635, 'Job 31:35', 'Job', 31, 35, '&nbsp;نو اے کاش چې ما ته چا غوږ نيولے وے. زۀ ليکلى درکوم چې هره يوه خبره رښتيا ده. او قادر خُدائ دې زما فرياد واورى، او زما مخالفين دې ليکلے اِلزام راوړى چې زۀ يې وګورم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12636, 'Job 31:36', 'Job', 31, 36, '&nbsp;بې‌شکه زۀ به په فخر سره د اِلزام مقابله وکړم او زۀ به دا د تاج په شان په سر کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12637, 'Job 31:37', 'Job', 31, 37, '&nbsp;زۀ به هغۀ له د خپل عمل حِساب کِتاب ورکړم، او د هغۀ په حضور کښې به زړَور ولاړ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12638, 'Job 31:38', 'Job', 31, 38, '&nbsp;کۀ ما هغه زمکه قبضه کړې وى چې کومه زۀ کرَم او دا مې د خپل اصلى مالِک نه اخستې وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12639, 'Job 31:39', 'Job', 31, 39, '&nbsp;کۀ د دې پېداوار ما بغېر د پېسو نه خوړلے وى، او کۀ ما د دې مالِکان وژلى وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12640, 'Job 31:40', 'Job', 31, 40, '&nbsp;نو پرېږده چې د غنمو په ځائ ازغى وشى، او د اوربشو په ځائ دې ګنده واښۀ وشى.“ د ايُوب خبرې ختمې شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12641, 'Job 32:1', 'Job', 32, 1, '&nbsp;نو دې درېو کسانو ايُوب له نور جواب ورنۀ کړو، ځکه چې ايُوب پخپله په خپل خيال کښې بې‌ګناه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12642, 'Job 32:2', 'Job', 32, 2, '&nbsp;نو بيا د رام د خاندان د بوزى براکيل زوئ اليهُو غصه شو. هغه ايُوب ته ځکه غصه شو چې ايُوب خپل ځان صحيح ګڼلو او په خُدائ پاک يې اِلزام لګولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12643, 'Job 32:3', 'Job', 32, 3, '&nbsp;هغه د ايُوب درېو ملګرو ته هم غصه وو ځکه چې هغوئ ايُوب له جواب نۀ شو ورکولے او داسې ښکارېده چې خُدائ پاک په غلطه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12644, 'Job 32:4', 'Job', 32, 4, '&nbsp;نو اليهُو د ايُوب سره د خبرو کولو دپاره د نورو کسانو انتظار کولو، ځکه چې هغوئ د هغۀ نه مشران وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12645, 'Job 32:5', 'Job', 32, 5, '&nbsp;خو چې کله اليهُو ته پته ولګېده چې د هغه درېو کسانو سره څۀ جواب نۀ وو، نو هغه غصه شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12646, 'Job 32:6', 'Job', 32, 6, '&nbsp;د بوزى براکيل زوئ اليهُو ووئيل، ”زۀ زلمے يم، او تۀ بوډا يې، نو په دې وجه زۀ يرېدم چې تا د خپلې رايې نه خبر کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12647, 'Job 32:7', 'Job', 32, 7, '&nbsp;ما وئيل چې مشران دې خبره وکړى، ځکه چې عقل د عُمر سره راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12648, 'Job 32:8', 'Job', 32, 8, '&nbsp;دا د قادر خُدائ روح دے چې بنيادم له پوهه ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12649, 'Job 32:9', 'Job', 32, 9, '&nbsp;صِرف مشران هوښيار نۀ وى، کله کله مشران هم په اِنصاف باندې نۀ پوهيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12650, 'Job 32:10', 'Job', 32, 10, '&nbsp;نو ځکه زۀ وايم چې ما ته غوږ ونيسئ، ما پرېږدئ چې د خپلې رايې اظهار هم وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12651, 'Job 32:11', 'Job', 32, 11, '&nbsp;ګوره، کله چې تا خبرې کولې نو ما څۀ نۀ وئيل، او ما ستا دليل ته غوږ نيولو، کله به چې تا سوچ کولو چې څۀ ووايم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12652, 'Job 32:12', 'Job', 32, 12, '&nbsp;ما تا ته توجو کوله، خو داسې هيڅ څوک نۀ وُو چې ايُوب يې غلط ثابت کړے وے، او په تاسو کښې داسې هيڅ څوک نۀ وُو چې د هغۀ د خبرې جواب يې ورکړے وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12653, 'Job 32:13', 'Job', 32, 13, '&nbsp;نو بيا دا مۀ وايئ چې مونږ ته عقل مِلاو شوے دے، پرېږده چې د انسان په ځائ خُدائ پاک هغۀ له جواب ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12654, 'Job 32:14', 'Job', 32, 14, '&nbsp;ايُوب ما سره نۀ تاسو سره بحث کولو، خو زۀ به هغۀ له ستاسو په شان جواب نۀ ورکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12655, 'Job 32:15', 'Job', 32, 15, '&nbsp;تاسو غلى ناست يئ، تاسو سره بل جواب نشته، تاسو يوه خبره هم نۀ شئ کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12656, 'Job 32:16', 'Job', 32, 16, '&nbsp;کله چې تاسو خاموش يئ نو زۀ به هم خاموش يم؟ ځکه چې تاسو هلته ولاړ يئ او بله يوه خبره هم نۀ شئ کولے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12657, 'Job 32:17', 'Job', 32, 17, '&nbsp;زۀ به هم خپل جواب ورکړم، زۀ به هم د خپلې رايې اظهار وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12658, 'Job 32:18', 'Job', 32, 18, '&nbsp;ځکه چې ما سره خبرې ډېرې دى، په ما کښې چې کوم روح دے هغه ما مجبوروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12659, 'Job 32:19', 'Job', 32, 19, '&nbsp;کۀ ما ته د خبرو کولو موقع مِلاو نۀ شى، نو زما برداشت ختم دے او زۀ به پړق وچوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12660, 'Job 32:20', 'Job', 32, 20, '&nbsp;زۀ به خبرې کوم، چې ما ته آرام مِلاو شى، او زۀ به جواب درکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12661, 'Job 32:21', 'Job', 32, 21, '&nbsp;زۀ به د هيچا طرفدارى نۀ کوم او زۀ به د چا چاپلوسى نۀ کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12662, 'Job 32:22', 'Job', 32, 22, '&nbsp;ځکه چې زۀ په چاپلوسۍ نۀ پوهېږم، ګنې زما پېدا کوونکى به زر ختم کړے وم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12663, 'Job 33:1', 'Job', 33, 1, '&nbsp;نو اے ايُوبه، زما خبرې واوره، او زۀ چې څۀ وايم نو هغې ته متوجو شه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12664, 'Job 33:2', 'Job', 33, 2, '&nbsp;نو اوس چې ما خبرې شروع کړې، نو پرېږده چې زړۀ تش کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12665, 'Job 33:3', 'Job', 33, 3, '&nbsp;زما ټولې خبرې سپينې دى، او زۀ رښتيا رښتيا وايم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12666, 'Job 33:4', 'Job', 33, 4, '&nbsp;د خُدائ پاک روح زۀ جوړ کړے يم، او د قادر خُدائ ساه ما له ژوند راکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12667, 'Job 33:5', 'Job', 33, 5, '&nbsp;کۀ تا سره څۀ جواب وى نو ما له يې راکړه، د خبرې دپاره ځان تيار کړه او په هغې ټينګ ودرېږه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12668, 'Job 33:6', 'Job', 33, 6, '&nbsp;ګوره، زۀ هم د خُدائ پاک په نظر کښې ستا په شان يم، زۀ هم د خټې نه جوړ شوے وم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12669, 'Job 33:7', 'Job', 33, 7, '&nbsp;نو زما نه مۀ يرېږه، او زۀ به تا سره زياتے نۀ کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12670, 'Job 33:8', 'Job', 33, 8, '&nbsp;تا زما په مخکښې خبرې کړې دى، او ما ستا ټولې خبرې اورېدلې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12671, 'Job 33:9', 'Job', 33, 9, '&nbsp;تۀ وائې چې، ”زۀ صفا او بې‌ګناه يم، زۀ معصُوم يم او په ما کښې هيڅ غلطى نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12672, 'Job 33:10', 'Job', 33, 10, '&nbsp;خو خُدائ پاک په ما کښې غلطى لټوى، هغه ما خپل دشمن ګڼى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12673, 'Job 33:11', 'Job', 33, 11, '&nbsp;هغه زما په پښو کښې زولنۍ اچوى، او زما په هر حرکت يې نظر دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12674, 'Job 33:12', 'Job', 33, 12, '&nbsp;خو په دې خبره کښې تۀ غلط يې. زۀ به تا ته ووايم چې ولې ځکه چې خُدائ پاک د انسان نه لوئ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12675, 'Job 33:13', 'Job', 33, 13, '&nbsp;تۀ په خُدائ پاک باندې اِلزام ولې لګوې، وائې چې هغه به زما د يوې خبرې جواب هم ونۀ کړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12676, 'Job 33:14', 'Job', 33, 14, '&nbsp;ځکه چې خُدائ پاک بار بار کلام کوى، خو خلق دې ته غوږ نۀ ږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12677, 'Job 33:15', 'Job', 33, 15, '&nbsp;کله چې بنى آدم په خوب اودۀ وى او هغه خوب وينى يا رويا وينى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12678, 'Job 33:16', 'Job', 33, 16, '&nbsp;نو خُدائ پاک به د هغوئ غوږونه کولاو کړى، او د خبردارى په ذريعه به هغوئ يروى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12679, 'Job 33:17', 'Job', 33, 17, '&nbsp;هغه يې د بدو عملونو نه راوګرځوى، او د غرور نه يې وساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12680, 'Job 33:18', 'Job', 33, 18, '&nbsp;هغه يې د مرګ نه بچ کوى، او د مرګ درياب د تېرېدو نه يې بچ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12681, 'Job 33:19', 'Job', 33, 19, '&nbsp;خُدائ پاک د بيمارۍ په ذريعه د خلقو اصلاح کوى، او د هغوئ په بدنونو باندې درد راولى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12682, 'Job 33:20', 'Job', 33, 20, '&nbsp;نو د هغوئ لوږه ختمه شى، او مزېدار خوراک ته يې هم زړۀ نۀ کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12683, 'Job 33:21', 'Job', 33, 21, '&nbsp;د هغوئ بدنونه ويلى شى، او دوه ګوتې مخ يې راوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12684, 'Job 33:22', 'Job', 33, 22, '&nbsp;هغوئ د مرګ په خولۀ ولاړ وى، او د مرګ فرښته د هغوئ انتظار کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12685, 'Job 33:23', 'Job', 33, 23, '&nbsp;خو کۀ د زرګونو فرښتو نه يوه فرښته راشى او چا ته صحيح لار وښائى نو دا بس دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12686, 'Job 33:24', 'Job', 33, 24, '&nbsp;او هغه په هغه کس باندې مِهربانه شى او ووائى چې، هغه بچ کړه چې قبر ته لاړ نۀ شى، ځکه چې ما ته د هغۀ د ژوند قيمت مِلاو شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12687, 'Job 33:25', 'Job', 33, 25, '&nbsp;د هغۀ بدن دې د ځوانۍ په وجه تازه شى، په هغۀ دې د ځوانۍ ورځې بيا راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12688, 'Job 33:26', 'Job', 33, 26, '&nbsp;بيا هغه خُدائ پاک ته سوال وکړى او سوال يې قبول شى، هغه په خوشحالۍ سره د خُدائ پاک حضور ته راشى، او هغه يې بيا يو نېک سړے جوړ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12689, 'Job 33:27', 'Job', 33, 27, '&nbsp;هغه به نورو کسانو ته وائى چې، ما ګناه کړې ده، او د نېکۍ په ځائ مې بدى کړې ده. او خُدائ پاک ما له د هغې سزا نۀ ده راکړې د څۀ چې زۀ لائق وم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12690, 'Job 33:28', 'Job', 33, 28, '&nbsp;خُدائ پاک زۀ د قبر نه بچ کړم، او زما ژوند به په رڼا کښې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12691, 'Job 33:29', 'Job', 33, 29, '&nbsp;بې‌شکه چې دا د خُدائ پاک کارونه دى، او د انسان دپاره يې بار بار کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12692, 'Job 33:30', 'Job', 33, 30, '&nbsp;هغه يې د قبر نه بچ کوى، او د ژوند په خوند يې پوهوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12693, 'Job 33:31', 'Job', 33, 31, '&nbsp;ايُوبه، ما ته توجو شه او ما ته غوږ ونيسه، تۀ خاموش اوسه او زۀ به خبرې کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12694, 'Job 33:32', 'Job', 33, 32, '&nbsp;کۀ تۀ څۀ وائې، نو ووايه، زۀ غواړم چې تا بې‌ګناه ثابت کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12695, 'Job 33:33', 'Job', 33, 33, '&nbsp;کۀ داسې نۀ وى، نو ما ته غوږ ونيسه، خاموش شه او زۀ به تا ته د عقل ښودنه وکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12696, 'Job 34:1', 'Job', 34, 1, '&nbsp;نو اليهُو خپله خبره جارى وساتله او وې وئيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12697, 'Job 34:2', 'Job', 34, 2, '&nbsp;”اے عقلمندو سړو، زما خبره واورئ، اے هوښيارانو ما ته غوږ ونيسئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12698, 'Job 34:3', 'Job', 34, 3, '&nbsp;ځکه چې غوږونه خبرې داسې معلوموى لکه څنګه چې ژبه د خوراک په خوند پوهيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12699, 'Job 34:4', 'Job', 34, 4, '&nbsp;راځئ چې د دې پته ولګوو چې څۀ صحيح دى، راځئ چې ښۀ څيزونه زده کړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12700, 'Job 34:5', 'Job', 34, 5, '&nbsp;ځکه چې ايُوب وئيلى دى چې زۀ بې‌ګناه يم، او خُدائ پاک زما سره اِنصاف نۀ کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');